export const C={G:6.67430e-11,c:299792458,hbar:6.62607015e-34/(2*Math.PI),k:1.380649e-23,AU:149597870700,day:86400,sun:1.98847e30,earth:5.9722e24,year:31557600};
export const G=C.G*C.sun*C.day**2/C.AU**3, EPS=1e-7;
export function blackHole(m){return {radius:2*C.G*m/C.c**2,temperature:C.hbar*C.c**3/(8*Math.PI*C.G*m*C.k),power:C.hbar*C.c**6/(15360*Math.PI*C.G**2*m**2),lifetime:5120*Math.PI*C.G**2*m**3/(C.hbar*C.c**4)}}
let uid=0;
export function body(name,type,m,x,y,vx,vy,color){return {id:++uid,name,type,m,x,y,vx,vy,color,trail:[]}}
export function radius(b){return b.type==='hole'?blackHole(b.m*C.sun).radius/C.AU:b.type==='star'?6.957e8*Math.cbrt(b.m)/C.AU:6.371e6*Math.cbrt(b.m/(C.earth/C.sun))/C.AU}
export function acceleration(bs){let a=bs.map(()=>[0,0]);for(let i=0;i<bs.length;i++)for(let j=i+1;j<bs.length;j++){let dx=bs[j].x-bs[i].x,dy=bs[j].y-bs[i].y,s=(dx*dx+dy*dy+EPS*EPS)**1.5;let ax=G*dx/s,ay=G*dy/s;a[i][0]+=bs[j].m*ax;a[i][1]+=bs[j].m*ay;a[j][0]-=bs[i].m*ax;a[j][1]-=bs[i].m*ay}return a}
export function mergeCollisions(bs,createBody=body){let count=0;for(let i=0;i<bs.length;i++)for(let j=i+1;j<bs.length;j++){let a=bs[i],b=bs[j];if(Math.hypot(a.x-b.x,a.y-b.y)<=radius(a)+radius(b)){let m=a.m+b.m;let heavy=a.m>=b.m?a:b;const merged=createBody(a.name+' + '+b.name,a.type==='hole'||b.type==='hole'?'hole':a.type==='star'||b.type==='star'?'star':'planet',m,(a.x*a.m+b.x*b.m)/m,(a.y*a.m+b.y*b.m)/m,(a.vx*a.m+b.vx*b.m)/m,(a.vy*a.m+b.vy*b.m)/m,heavy.color);bs[i]=merged;bs.splice(j,1);count++;return count+mergeCollisions(bs,createBody)}}return count}
export function step(bs,dt,createBody=body){let a=acceleration(bs);bs.forEach((b,i)=>{b.x+=b.vx*dt+.5*a[i][0]*dt*dt;b.y+=b.vy*dt+.5*a[i][1]*dt*dt});let z=acceleration(bs);bs.forEach((b,i)=>{b.vx+=.5*(a[i][0]+z[i][0])*dt;b.vy+=.5*(a[i][1]+z[i][1])*dt});return mergeCollisions(bs,createBody)}
export function safeStep(bs){let dt=.5;for(let i=0;i<bs.length;i++)for(let j=i+1;j<bs.length;j++){let a=bs[i],b=bs[j],r=Math.max(EPS,Math.hypot(a.x-b.x,a.y-b.y)),v=Math.hypot(a.vx-b.vx,a.vy-b.vy);dt=Math.min(dt,.015*Math.sqrt(r**3/(G*(a.m+b.m))),.15*r/(v+1e-30))}return Math.max(1e-10,dt)}
export function energy(bs){let e=bs.reduce((s,b)=>s+.5*b.m*(b.vx*b.vx+b.vy*b.vy),0);for(let i=0;i<bs.length;i++)for(let j=i+1;j<bs.length;j++)e-=G*bs[i].m*bs[j].m/Math.sqrt((bs[i].x-bs[j].x)**2+(bs[i].y-bs[j].y)**2+EPS**2);return e}
export function scenario(name){let bs=[];if(name==='binary'){let v=Math.sqrt(G/4);bs=[body('Stern A','star',1,-.5,0,0,-v,'#ffd19a'),body('Stern B','star',1,.5,0,0,v,'#bba8ff')]}else if(name==='hole'){bs=[body('Schwarzes Loch','hole',1,0,0,0,0,'#bb92ff'),body('Erde','planet',C.earth/C.sun,1,0,0,Math.sqrt(G),'#6cceec')]}else{bs=[body('Sonne','star',1,0,0,0,0,'#ffd19a')];let planets=[['Merkur',.387,1.6601e-7,'#c1aaa0'],['Venus',.723,2.4478e-6,'#e9c18d'],['Erde',1,C.earth/C.sun,'#6cceec'],['Mars',1.524,3.227e-7,'#e38976'],['Jupiter',5.203,.0009546,'#cfac92'],['Saturn',9.537,.0002858,'#ddc9a0'],['Uranus',19.19,.00004366,'#a3e5df'],['Neptun',30.07,.00005151,'#729bf5']];planets.forEach(([n,r,m,c],i)=>{let t=i*1.25;bs.push(body(n,'planet',m,r*Math.cos(t),r*Math.sin(t),-Math.sqrt(G/r)*Math.sin(t),Math.sqrt(G/r)*Math.cos(t),c))})}let m=bs.reduce((s,b)=>s+b.m,0),vx=bs.reduce((s,b)=>s+b.m*b.vx,0)/m,vy=bs.reduce((s,b)=>s+b.m*b.vy,0)/m;bs.forEach(b=>{b.vx-=vx;b.vy-=vy});return bs}

